userDefinedLinkHintCss:
/* Generated by theme-ssot — do not edit by hand */
:root {
  --vimium-accent: #aacade;
  --vimium-accent-fg: #1a1008;
  --vimium-secondary: #b9cdd7;
  --vimium-tertiary: #c6b1a2;
  --vimium-outline: #92a7b6;
  --vimium-text: #ebe1d4;
  --vimium-muted: #d1c5b4;
  --vimium-surface2: #385257;
  --vimium-surface1: #202e31;
  --vimium-surface0: #192325;
  --vimium-base: #0d1112;
  --vimium-mantle: #111718;

  --vimium-foreground-text-color: #ebe1d4;
  --vimium-background-text-color: #ebe1d4;
  --vimium-foreground-color: #111718;
}

/* Hints: hardcoded hex (no var()) so defaults cannot win if :root fails */
div > .vimiumHintMarker,
div.vimiumHintMarker,
div.internal-vimium-hint-marker {
  background: #aacade !important;
  background-image: none !important;
  border: 1px solid #111718 !important;
  box-shadow: none !important;
  padding: 3px 4px !important;
}

div > .vimiumHintMarker span,
div.vimiumHintMarker span,
div.internal-vimium-hint-marker span {
  color: #1a1008 !important;
  font-weight: bold !important;
  font-size: 12px !important;
  text-shadow: none !important;
}

div > .vimiumHintMarker > .matchingCharacter,
div.vimiumHintMarker > .matchingCharacter,
div.internal-vimium-hint-marker > .matchingCharacter {
  color: #385257 !important;
}

/* vomnibar */
#vomnibar {
  background: #0d1112 !important;
  border: 2px solid #92a7b6 !important;
}

#vomnibar input,
#vomnibar #vomnibar-search-area,
#vomnibar ul {
  color: #ebe1d4 !important;
  background: #0d1112 !important;
  border: none !important;
  box-shadow: none !important;
}

#vomnibar li {
  border-bottom: 1px solid #192325 !important;
}

#vomnibar li .source {
  color: #c6b1a2 !important;
}

#vomnibar li em,
#vomnibar li .title,
#vomnibar li .title .match,
#vomnibar li .match {
  color: #aacade !important;
  font-weight: bold !important;
}

#vomnibar li .url {
  color: #b9cdd7 !important;
}

#vomnibar li.selected {
  background-color: #192325 !important;
}

/* hud */
div#hud-container {
  background: #0d1112 !important;
  border: 1px solid #ebe1d4 !important;
  box-shadow: none !important;
}

div#hud-container span#hud-find-input,
div#hud-container div#hud {
  color: #ebe1d4 !important;
}

div#hud-container .hud-find,
div#hud-container #search-area {
  background-color: #0d1112 !important;
}

::selection {
  background-color: #c6b1a2 !important;
  color: #1a1008 !important;
}
